"""Neuron cards: a compact, label-free view of any of the 442,368 neurons, from the corpus scan and the weights.

  python -m bonsai_interp.graph.play card --neuron bonsai1/L9/N3688+ [--k 6] [--out card.json|card.md]

A card holds, for both poles: the top corpus examples with the peak token in ⟦ ⟧, the pole's corpus max,
its activation density (share of all scanned tokens above 0.1 and 0.3 of that max, read from the scan's
log-binned histograms), and the sign-regime split. It adds the direct logit effect of the neuron's output
direction (final norm gain, then the unembedding; weights only, read on the CPU) and flags for units an
8 + 8 test can't pass (dense, positional). No GPU and no model load: a card takes a few seconds.
"""
import json
from functools import lru_cache

import numpy as np

from bonsai_interp import explore
from bonsai_interp.graph.contrib import NEURON, ROOT

# flags (calibrated on the poles contributors marked dense / positional, against held token poles)
DENSE_10 = 0.10     # >= 10% of tokens above 0.1 of max: an 8 + 8 test can hardly pass
BROAD_10 = 0.01     # >= 1%: near misses will often fire weakly
POSITIONAL = 0.5    # >= half of the top 32 peaks within the first 16 tokens of a window, or one position


def parse(neuron):
    """'bonsai1/L9/N3688+' or 'L9/N3688' or '9/3688' -> (model, L, n, pole or None)."""
    m = NEURON.match(neuron)
    if m:
        return m["model"], int(m["L"]), int(m["n"]), m["pole"]
    s = neuron.removeprefix("bonsai1/").replace("L", "").replace("N", "")
    pole = s[-1] if s[-1] in "+-" else None
    L, n = map(int, s.rstrip("+-").split("/"))
    return "bonsai1", L, n, pole


def _above(h, lower, upper, t):
    """Count in a log-binned histogram above threshold t, splitting the straddling bin log-uniformly."""
    b = int(np.searchsorted(lower, t, side="right")) - 1  # lower[b] <= t < lower[b+1]
    n = h[b + 1:].sum()
    lo, hi = lower[b], upper[b]
    if lo > 0 and np.isfinite(hi) and hi > t:
        n += h[b] * (np.log(hi) - np.log(t)) / (np.log(hi) - np.log(lo))
    elif lo == 0 and hi > t:
        n += h[b] * (hi - t) / hi
    return float(n)


def pole_stats(name, L, n, pole):
    s = explore.scan(name)
    pi, regs = (0, [0, 1]) if pole == "+" else (1, [2, 3])
    mx = float(s["top_val"][L, pi, 0, n])
    h = s["hist"][L, n]  # (4 regimes, NB); bin b holds |a| in (bins[b-1], bins[b]]
    bins = s["bins"].astype(np.float64)
    lower, upper = np.concatenate([[0], bins]), np.concatenate([bins, [np.inf]])
    total = float(h.sum())
    pole_h = h[regs].sum(0)
    dens = {f: _above(pole_h, lower, upper, f * mx) / total for f in (0.1, 0.3)}
    split = {}
    for r in regs:  # regime shares among this pole's activations above 0.1 of max
        split[explore.REGIMES[r]] = _above(h[r], lower, upper, 0.1 * mx)
    tot = sum(split.values())
    split = {k: round(v / tot, 3) if tot else None for k, v in split.items()}
    pos = s["top_pos"][L, pi, :, n]
    pos = pos[np.isfinite(s["top_val"][L, pi, :, n])]
    vals, counts = np.unique(pos, return_counts=True)
    early, mode_share = float((pos < 16).mean()) if len(pos) else 0.0, float(counts.max() / len(pos)) if len(pos) else 0.0
    return {"max": round(mx, 3), "density": {"0.1": round(dens[0.1], 5), "0.3": round(dens[0.3], 5)},
            "regimes": split, "peak_positions": {"first16": round(early, 3), "commonest": int(vals[counts.argmax()]) if len(pos) else None,
                                                  "commonest_share": round(mode_share, 3)}}


def flags(st):
    out = []
    d = st["density"]["0.1"]
    if d >= DENSE_10:
        out.append(f"dense: {d:.1%} of tokens reach 0.1 of max; an 8 + 8 test can hardly pass (consider unit_kind 'dense / positional')")
    elif d >= BROAD_10:
        out.append(f"broad: {d:.1%} of tokens reach 0.1 of max; near misses will often fire weakly")
    pp = st["peak_positions"]
    if pp["first16"] >= POSITIONAL or pp["commonest_share"] >= POSITIONAL:
        out.append(f"positional: top peaks cluster at window position {pp['commonest']} "
                   f"({pp['commonest_share']:.0%}; {pp['first16']:.0%} within the first 16 tokens)")
    if st["regimes"]:
        echo = max(st["regimes"], key=lambda k: st["regimes"][k] or 0)
        if echo in ("-x- echo", "-g +u leak") and (st["regimes"][echo] or 0) >= 0.6:
            out.append(f"gate-closed regime dominates ({echo} {st['regimes'][echo]:.0%})")
    return out


@lru_cache(None)
def _weights(name):
    """(down_proj column reader, final norm gain in fp32, unembedding in fp16) on the CPU, from the
    unpacked safetensors or from the 1-bit GGUF (bonsai_interp.gguf_weights), whichever the folder holds."""
    from bonsai_interp.model import MODELS
    path = MODELS[name]
    if not (path / "model.safetensors.index.json").exists():
        from bonsai_interp import gguf_weights
        ts = gguf_weights.by_name(path)
        col = lambda L, n: gguf_weights.column(ts[f"model.layers.{L}.mlp.down_proj.weight"], n)
        return col, gguf_weights.dense(ts["model.norm.weight"]), gguf_weights.dense(ts["lm_head.weight"]).half()
    from safetensors import safe_open
    idx = json.loads((path / "model.safetensors.index.json").read_text())["weight_map"]
    def get(t):
        with safe_open(str(path / idx[t]), "pt", device="cpu") as h:
            return h.get_tensor(t)
    def col(L, n):
        t = f"model.layers.{L}.mlp.down_proj.weight"
        with safe_open(str(path / idx[t]), "pt", device="cpu") as h:
            return h.get_slice(t)[:, n:n + 1][:, 0].float()
    return col, get("model.norm.weight").float(), get("lm_head.weight")


def direct_logits(name, L, n, k=12):
    """Tokens the + pole's output direction promotes / suppresses directly (the - pole does the reverse):
    W_U (g * d), d = down_proj column n, g = final RMSNorm gain. Same as probe/induce.py `direct`."""
    col, g, wu = _weights(name)
    d = col(L, n)
    logits = _matvec(wu, g * d)
    tok = explore.tokenizer()
    top, bot = logits.topk(k), (-logits).topk(k)
    return {"promotes": [[tok.decode([i]), round(v, 3)] for i, v in zip(top.indices.tolist(), top.values.tolist())],
            "suppresses": [[tok.decode([i]), round(-v, 3)] for i, v in zip(bot.indices.tolist(), bot.values.tolist())],
            "note": "for the + pole, per unit activation, before the final RMS normalisation; the - pole swaps the lists"}


def _matvec(w, v, chunk=16384):
    """fp16 matrix x fp32 vector in chunks (keeps memory at a few hundred MB)."""
    import torch
    return torch.cat([w[i:i + chunk].float() @ v for i in range(0, w.shape[0], chunk)])


def card(neuron, k=6, logits=True, before=40, after=8):
    name, L, n, pole = parse(neuron)
    out = {"neuron": f"{name}/L{L}/N{n}", "focus": pole, "poles": {}}
    for p in ("+", "-"):
        st = pole_stats(name, L, n, p)
        ex = explore.examples(name, L, n, 0 if p == "+" else 1, k, before=before, after=after)
        st["examples"] = [{"act": round(v, 3), "frac": round(v / st["max"] * (1 if p == "+" else -1), 3) if st["max"] else None,
                           "regime": r, "text": t} for v, r, w, pos, t in ex]
        st["flags"] = flags(st)
        out["poles"][p] = st
    if logits:
        try:
            out["direct"] = direct_logits(name, L, n)
        except (FileNotFoundError, KeyError, OSError) as e:
            out["direct"] = {"error": f"weights unavailable: {e.__class__.__name__}"}
    rec = record(name, L, n)
    out["records"] = {p: {"status": r["status"], "label": r.get("label"), "short": r.get("short")} for p, r in rec.items()}
    return out


def record(name, L, n):
    """Derived graph records for the two poles, if any ({pole: record})."""
    out = {}
    for p, suf in (("+", "pos"), ("-", "neg")):
        f = ROOT / "graph" / "neurons" / name / f"L{L}_N{n}_{suf}.json"
        if f.exists():
            out[p] = json.loads(f.read_text(encoding="utf-8"))
    return out


def render(c):
    lines = [f"=== {c['neuron']}  (card: scan + weights; not a tested label)"]
    for p in sorted(c["poles"], key=lambda p: p != (c["focus"] or "+")):
        st = c["poles"][p]
        rec = c["records"].get(p)
        lines.append(f"--- {p} pole   max {st['max']:.2f}   density >0.1·max {st['density']['0.1']:.3%}  >0.3·max {st['density']['0.3']:.3%}"
                     f"   regimes {', '.join(f'{k} {v:.0%}' for k, v in st['regimes'].items() if v is not None)}")
        lines.append(f"    record: {rec['status']}: {rec['label']}" if rec else "    record: none (unsurveyed)")
        for f in st["flags"]:
            lines.append(f"    FLAG {f}")
        for e in st["examples"]:
            lines.append(f"    {e['act']:8.2f} {e['regime']:>10} | {e['text'][-110:]}")
    d = c.get("direct")
    if d and "error" not in d:
        lines.append("--- direct logit effect of the output direction (+ pole; the - pole reverses it)")
        lines.append("    promotes:   " + "  ".join(repr(t) for t, _ in d["promotes"]))
        lines.append("    suppresses: " + "  ".join(repr(t) for t, _ in d["suppresses"]))
    elif d:
        lines.append(f"--- direct logit effect: {d['error']}")
    return "\n".join(lines)


def main(a):
    c = card(a.neuron, k=a.k, logits=not a.no_logits)
    print(render(c))
    if a.out:
        from pathlib import Path
        p = Path(a.out)
        p.write_text(json.dumps(c, ensure_ascii=False, indent=1) + "\n" if p.suffix == ".json" else render(c) + "\n",
                     encoding="utf-8", newline="\n")
        print(f"wrote {p}")


def compact(c, k=4, pre=70, post=24, tokens=8):
    """A small form of a card for the survey site: about 1.5 KB per neuron.
    {"+"/"-": {"m": max, "d": [density 0.1, 0.3], "r": [gate-open share, gate-closed share], "f": [flag words],
               "x": [[act, before, peak token, after], ...]}, "u": [[promoted by +], [suppressed by +]]}"""
    out = {}
    for p, st in c["poles"].items():
        xs = []
        for e in st["examples"][:k]:
            a, rest = e["text"].split("⟦", 1)
            b, after = rest.split("⟧", 1)
            xs.append([round(e["act"], 2), a[-pre:], b, after[:post]])
        out[p] = {"m": round(st["max"], 2), "d": [st["density"]["0.1"], st["density"]["0.3"]],
                  "r": [v if v is not None else 0 for v in st["regimes"].values()],
                  "f": [f.split(":")[0].split(" ")[0] for f in st["flags"]], "x": xs}
    d = c.get("direct") or {}
    if "promotes" in d:
        out["u"] = [[t for t, _ in d["promotes"][:tokens]], [t for t, _ in d["suppresses"][:tokens]]]
    return out
"""Validate the graph (no model or torch needed).

  python -m bonsai_interp.graph.validate             contributions only (what a PR is checked against)
  python -m bonsai_interp.graph.validate --strict    also: derived files on disk match the fold exactly (main)

Checks every contribution and pre-registration file against the rules in graph/SCHEMA.md and
DATA_POLICY.md, then checks that the committed neuron records, edges and index are exactly what
`fold` produces from the contributions (so no record was edited by hand).
"""
import json
import sys

from bonsai_interp.graph import contrib, fold

ROOT = contrib.ROOT


def main():
    errs = []
    results = contrib.load_all()
    ids = {}
    for path, c in results:
        errs += contrib.check(path, c)
        if c.get("id") in ids:
            errs.append(f"duplicate contribution id {c['id']} ({ids[c['id']]} and {path.relative_to(ROOT).as_posix()})")
        ids[c.get("id")] = path.relative_to(ROOT).as_posix()
    tests = sorted(contrib.C.glob("*/*/*.tests.json"))
    for p in tests:
        errs += contrib.check_tests_file(p)
    stray = [p for p in contrib.C.rglob("*") if p.is_file() and p.suffix not in (".json", ".md")]
    errs += [f"{p.relative_to(ROOT).as_posix()}: only .json and .md files are allowed under graph/contributions" for p in stray]
    files = fold.fold()
    if "--strict" in sys.argv:  # on main, after the merge agent's fold commit: derived files must match exactly
        for p, s in files.items():
            if not (ROOT / p).exists() or (ROOT / p).read_text(encoding="utf-8") != s:
                errs.append(f"{p}: out of date with the contributions (run python -m bonsai_interp.graph.fold and commit)")
        for p in (ROOT / "graph" / "neurons").glob("*/*.json"):
            if p.relative_to(ROOT).as_posix() not in files:
                errs.append(f"{p.relative_to(ROOT).as_posix()}: record with no contributions (records are derived; do not add them by hand)")
    neurons = set(json.loads(files["graph/index.json"])["neurons"])
    for e in json.loads(files["graph/edges.json"])["edges"]:
        for end in ("from", "to"):
            if e[end] not in neurons:
                errs.append(f"edge {e['from']} -> {e['to']} ({e['contribution']}): {e[end]} has no contributions of its own")
    for m in errs:
        print("ERROR", m)
    print(f"{len(results)} contributions, {len(tests)} pre-registration files, {len(neurons)} neuron poles; {len(errs)} problems")
    sys.exit(1 if errs else 0)


if __name__ == "__main__":
    main()

"""Forward view of a neuron from a corpus scan: top examples per pole, regime stats.

Usage: python -m bonsai_interp.explore --model bonsai1 --neuron 18/4242 [--pole +] [--k 12]
"""
import argparse
from functools import lru_cache

import numpy as np
from transformers import AutoTokenizer

from bonsai_interp.model import MODELS, ROOT

REGIMES = ["+x+", "-x- echo", "+g -u", "-g +u leak"]


@lru_cache(None)
def scan(name):
    return dict(np.load(ROOT / "data" / f"scan_{name}.npz"))


@lru_cache(None)
def corpus():
    return np.load(ROOT / "data" / "corpus.npz")["tokens"]


@lru_cache(None)
def tokenizer():
    return AutoTokenizer.from_pretrained(MODELS["bonsai1"])


def examples(name, L, n, pole=0, k=12, before=48, after=8):
    """[(activation, regime, window, pos, text with the peak token in ⟦ ⟧)]"""
    s, tok, toks = scan(name), tokenizer(), corpus()
    out = []
    for j in range(k):
        v = s["top_val"][L, pole, j, n]
        if not np.isfinite(v):
            break
        w, p, r = s["top_win"][L, pole, j, n], int(s["top_pos"][L, pole, j, n]), s["top_reg"][L, pole, j, n]
        ids = toks[w]
        text = tok.decode(ids[max(0, p - before):p]) + "⟦" + tok.decode(ids[p:p + 1]) + "⟧" + \
            tok.decode(ids[p + 1:p + 1 + after])
        out.append((float(v) * (1 if pole == 0 else -1), REGIMES[r], int(w), p, text.replace("\n", "⏎")))
    return out


def regime_stats(name, L, n):
    """Share of each regime among activations above 10% / 30% of each pole's max."""
    s = scan(name)
    h, bins = s["hist"][L, n], s["bins"]  # (4, NB): bin b holds |a| in [bins[b-1], bins[b])
    lower = np.concatenate([[0], bins])
    res = {}
    for pole, regs in (("+", [0, 1]), ("-", [2, 3])):
        mx = abs(s["top_val"][L, 0 if pole == "+" else 1, 0, n])
        for frac in (0.1, 0.3):
            mask = lower >= frac * mx
            counts = h[regs][:, mask].sum(1)
            tot = counts.sum()
            res[f"{pole}pole>{int(frac * 100)}%max"] = {
                "count": int(tot),
                **{REGIMES[r]: round(float(c) / tot, 3) if tot else None for r, c in zip(regs, counts)}}
        res[f"{pole}max"] = float(mx)
    return res


def show(name, L, n, poles=("+", "-"), k=12):
    print(f"=== {name} L{L}/N{n}")
    for key, v in regime_stats(name, L, n).items():
        print(f"  {key}: {v}")
    for pole in poles:
        print(f"--- {pole} pole")
        for v, r, w, p, text in examples(name, L, n, 0 if pole == "+" else 1, k):
            print(f"{v:9.2f} {r:>10} | {text}")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--model", default="bonsai1")
    ap.add_argument("--neuron", required=True)
    ap.add_argument("--pole", default="+-")
    ap.add_argument("--k", type=int, default=12)
    a = ap.parse_args()
    L, n = map(int, a.neuron.split("/"))
    show(a.model, L, n, tuple(a.pole), a.k)
"""Contributions: immutable, append-only files that are the only way information enters the graph.

Layout (one folder per neuron pole):

  graph/contributions/<model>/L{L}_N{n}_{pos|neg}/<id>.tests.json   pre-registration (committed FIRST)
  graph/contributions/<model>/L{L}_N{n}_{pos|neg}/<id>.json         results (committed in a LATER commit)

`<id>` is `YYYY-MM-DD-<github handle>-<4+ chars>`, unique forever. Contributions are never edited
or deleted; a correction is a new contribution. Neuron records under graph/neurons/ are derived
from contributions by `fold` and are never edited by hand.

Kinds: interpret (label a pole), qc (re-test a label), replicate (blind clean-room run), map (edges only).
"""
import json
import re
from pathlib import Path

from bonsai_interp.graph.protocols import LEGACY, PROTOCOLS

ROOT = Path(__file__).resolve().parents[2]
C = ROOT / "graph" / "contributions"
KINDS = {"interpret", "qc", "replicate", "map"}
QC_VERDICTS = {"confirm", "dispute", "refine"}
ID = re.compile(r"^\d{4}-\d{2}-\d{2}-[A-Za-z0-9-]+-[A-Za-z0-9]{4,}$|^core-[a-z0-9-]+$")
NEURON = re.compile(r"^(?P<model>[a-z0-9_]+)/L(?P<L>\d+)/N(?P<n>\d+)(?P<pole>[+-])$")
LOCAL_PATH = re.compile(r"(?i)\b[a-z]:[\\/]+users[\\/]|/home/[a-z]|/Users/[A-Za-z]")
MAX_FILE = 64 * 1024
METHODS_REQUIRED_FROM = "2026-10-18T18:30"  # contributions created earlier predate the methods block
MAX_NOTES = 4000
MAX_EXAMPLE = 400


def folder_for(neuron):
    m = NEURON.match(neuron)
    return C / m["model"] / f"L{m['L']}_N{m['n']}_{'pos' if m['pole'] == '+' else 'neg'}"


def load_all():
    """[(path, contribution)] for every results file, in deterministic order."""
    out = []
    for p in sorted(C.glob("*/*/*.json")):
        if p.name.endswith(".tests.json"):
            continue
        out.append((p, json.loads(p.read_text(encoding="utf-8"))))
    return out


def check(path: Path, c: dict):
    """Problems with one results file (empty list = fine)."""
    errs = []
    say = errs.append
    rel = path.relative_to(ROOT).as_posix()
    if path.stat().st_size > MAX_FILE:
        say(f"{rel}: larger than {MAX_FILE // 1024} KB; move bulky material to the library and list it under 'artifacts'")
    if LOCAL_PATH.search(path.read_text(encoding="utf-8")):
        say(f"{rel}: contains a local filesystem path")
    for k in ("id", "kind", "neuron", "created", "contributor"):
        if not c.get(k):
            say(f"{rel}: needs '{k}'")
    if errs:
        return errs
    if not ID.match(c["id"]) or path.stem != c["id"]:
        say(f"{rel}: id must match the file name and look like YYYY-MM-DD-<handle>-<suffix>")
    if c["kind"] not in KINDS:
        say(f"{rel}: kind must be one of {sorted(KINDS)}")
    if not NEURON.match(c["neuron"]) or folder_for(c["neuron"]) != path.parent:
        say(f"{rel}: neuron {c['neuron']!r} does not match its folder")
    if not c["id"].startswith("core-") and c["kind"] in ("interpret", "qc", "replicate") and c["created"] >= METHODS_REQUIRED_FROM:
        mt = c.get("methods") or {}
        if not mt.get("agent") or not isinstance(mt.get("screens"), list) or not mt.get("screens"):
            say(f"{rel}: needs a 'methods' block with 'agent' and a non-empty 'screens' list (see bonsai_interp/graph/methods.py)")
    if c["kind"] in ("interpret", "qc") and not c.get("tests"):
        say(f"{rel}: an {c['kind']} contribution needs at least one pre-registered test")
    if c["kind"] == "interpret" and not c.get("label"):
        say(f"{rel}: an interpret contribution needs a 'label'")
    if c["kind"] == "qc":
        q = c.get("qc") or {}
        if q.get("verdict") not in QC_VERDICTS:
            say(f"{rel}: qc.verdict must be one of {sorted(QC_VERDICTS)}")
        if q.get("verdict") == "refine" and not c.get("label"):
            say(f"{rel}: a 'refine' QC must propose a new 'label'")
    for i, t in enumerate(c.get("tests", [])):
        proto = LEGACY.get(t.get("protocol"), t.get("protocol"))
        if proto not in PROTOCOLS:
            say(f"{rel}: tests[{i}] protocol {t.get('protocol')!r} unknown (known: {sorted(PROTOCOLS)})")
        tf = t.get("tests_file")
        if not tf:
            say(f"{rel}: tests[{i}] needs 'tests_file' (the pre-registration)")
